SELECT 'MATERIAL' AS kind, spec_id, product_id, segment_id, COALESCE(definition_id, material_class_id, '') AS ref_id, material_use AS use_or_key, quantity, COALESCE(uom, '') AS uom FROM emc_product_segment_material_spec WHERE COALESCE(NULLIF(TRIM(?), ''), product_id) = product_id UNION ALL SELECT 'EQUIPMENT', spec_id, product_id, segment_id, COALESCE(NULLIF(equipment_id, ''), equipment_class_id, ''), equipment_use, quantity, '' FROM emc_product_segment_equipment_spec WHERE COALESCE(NULLIF(TRIM(?), ''), product_id) = product_id UNION ALL SELECT 'PERSONNEL', spec_id, product_id, segment_id, COALESCE(NULLIF(person_id, ''), personnel_class_id, ''), personnel_use, quantity, '' FROM emc_product_segment_personnel_spec WHERE COALESCE(NULLIF(TRIM(?), ''), product_id) = product_id UNION ALL SELECT 'PARAMETER', spec_id, product_id, segment_id, param_key, COALESCE(param_name, ''), CAST(0 AS NUMERIC), COALESCE(uom, '') FROM emc_product_segment_parameter_spec WHERE COALESCE(NULLIF(TRIM(?), ''), product_id) = product_id
